const raw = $input.first().json || {};

// ---------------------------------------------------------------- security ---
// THIS WEBHOOK HAD NO AUTHENTICATION OF ANY KIND until 2026-08-25: no credential on the
// trigger node (`options: {}`), and nothing anywhere in this flow ever looked at the request.
// Anyone who knew the URL could start a run. The shared secret below is the same one the five
// sibling audit flows already require - see cc-below-agreed/nodes/Validate_Inputs.js.
//
// NOT A REAL SECRET AGAINST AN INSIDER: it travels in plaintext, appears in every execution's
// stored request data, and is compared against a constant below, so anyone with read access to
// this n8n project can see it. It exists to keep strangers out, not colleagues. Moving it into
// an `httpHeaderAuth` credential on the Webhook node is still the open item; that needs a UI
// click, which the n8n API cannot do.
//
// WHY THE CHECK IS WRITTEN AS A GATE. `Run (webhook)` is this flow's only request trigger, so
// on the production path `viaHttp` is always true and the secret is always required. It is
// still written as a gate rather than an unconditional check so that a manual run from the
// n8n UI - pinned data, no HTTP envelope - does not have to carry a secret it has no way to
// send. That is not a hole: reaching the manual runner already requires an authenticated n8n
// session, which is a far stronger credential than this header. All 8 recorded runs of this
// flow to date were mode 'manual'.
//
// THE DISCRIMINATOR IS `raw.headers`, NOT `raw.body`. n8n's webhook node always builds the
// envelope { headers, params, query, body, webhookUrl, executionMode } and sets `headers`
// itself, so a caller cannot remove it. `raw.body` can be made to vanish by POSTing a literal
// `null` body - which would skip this check on the exact path that needs it. Any existing
// `raw.body` test in this node is about payload SHAPE and is left as it is; this one is about
// provenance and has to be the unspoofable of the two.
const viaHttp = raw.headers !== null && typeof raw.headers === 'object';

// Header names arrive lowercased from n8n's webhook node; read defensively anyway so a proxy
// that preserves case cannot bypass the check.
function webhookHeader(name) {
  const want = name.toLowerCase();
  const h = raw.headers || {};
  for (const k of Object.keys(h)) {
    if (k.toLowerCase() === want) return String(h[k] || '');
  }
  return '';
}

// Length-independent compare. Not a defence against a real timing attack over the internet
// (jitter swamps it), but it costs nothing and stops the trivial prefix-probing case.
function safeEqual(a, b) {
  const A = String(a), B = String(b);
  let diff = A.length ^ B.length;
  for (let i = 0; i < Math.max(A.length, B.length); i++) {
    diff |= (A.charCodeAt(i) || 0) ^ (B.charCodeAt(i) || 0);
  }
  return diff === 0;
}

// THE ACCEPTED SECRETS, AS A SET, AND THE SET IS THE POINT. A single literal has no rotation
// ordering that avoids an outage: change the caller first and every call is rejected here;
// change here first and every call is rejected by the caller's old value. So the check takes a
// SET and both slots are accepted at once. Rotation is: (1) add the new secret here, (2) switch
// the caller, (3) confirm from the secret_slot_matched log line below that live traffic is
// arriving on the new slot, (4) remove the old entry.
//
// Slot names are logged, VALUES ARE NEVER LOGGED. 'live' is the value the sibling flows have
// been accepting all along; 'rotating' is its replacement.
const ACCEPTED_WEBHOOK_SECRETS = [
  { slot: 'live',     value: 'LAWP' },
  { slot: 'rotating', value: 'OAhz0nSVf3rtx7oSquAK-8xJrlUYdfKERWV217qpk40' }
];

let secretSlot = '';
if (viaHttp) {
  const providedSecret = webhookHeader('x-sr-webhook-secret');
  // EVERY slot is compared, and the loop does not break early: bailing out on the first match
  // would make the number of comparisons depend on which slot matched, which is the timing
  // leak safeEqual exists to avoid. matchedSlot is assigned, not returned.
  let matchedSlot = '';
  for (let i = 0; i < ACCEPTED_WEBHOOK_SECRETS.length; i++) {
    const cand = ACCEPTED_WEBHOOK_SECRETS[i];
    if (providedSecret && safeEqual(providedSecret, cand.value)) matchedSlot = cand.slot;
  }
  if (!matchedSlot) {
    // DELIBERATELY NOT SILENT, and this is the ONE place this flow departs from the siblings.
    // They suppress the alert email on an unauthorized because an anonymous caller can trigger
    // that branch at will, which would hand anyone who found the URL a mail-bomb. Here the
    // opposite risk dominates: this endpoint has NEVER required the header, so the most likely
    // first rejection is a LEGITIMATE caller that this change has just broken, and that must be
    // loud and visible rather than a quiet entry in the execution list. Throwing marks the
    // execution as an error, which is retained here (saveDataErrorExecution: 'all') and
    // surfaces wherever failures are watched.
    //
    // Terse on purpose - do not tell an unauthenticated caller which part failed.
    throw new Error('unauthorized');
  }
  secretSlot = matchedSlot;
}
// -------------------------------------------------------------- end security ---
const body = raw.body || raw;
const auth = body.erp_auth || {};
const errors = [];
const bearer = String(auth.bearer || '').trim();
const deviceId = String(auth.device_id || '').trim();
if (!/^Bearer\s+\S+/.test(bearer)) errors.push('erp_auth.bearer missing');
if (!/^\d+$/.test(deviceId)) errors.push('erp_auth.device_id missing');
let tokenUser = null;
if (errors.length === 0) {
  try {
    const seg = bearer.replace(/^Bearer\s+/, '').split('.')[1];
    const claims = JSON.parse(Buffer.from(seg, 'base64').toString('utf8'));
    tokenUser = claims.user || null;
    if (claims.device && String(claims.device) !== deviceId) errors.push('device_id does not match the bearer device claim');
    if (claims.exp && Number(claims.exp) * 1000 < Date.now()) errors.push('bearer has expired');
  } catch (e) { errors.push('bearer is not a decodable JWT'); }
}
const p = body.params || {};
const smoke = p.smoke === true;
function lastMonth() {
  const d = new Date();
  let y = d.getUTCFullYear(); let mo = d.getUTCMonth() - 1;
  if (mo < 0) { mo = 11; y -= 1; }
  const from = y + '-' + String(mo + 1).padStart(2, '0') + '-01';
  const to = new Date(Date.UTC(y, mo + 1, 0)).toISOString().slice(0, 10);
  return { from: from, to: to };
}
const def = lastMonth();
const from = String(p.window_from || def.from).trim();
const to = String(p.window_to || def.to).trim();
const defaulted = !p.window_from || !p.window_to;
if (!/^\d{4}-\d{2}-\d{2}$/.test(from)) errors.push('params.window_from must be YYYY-MM-DD, got: ' + from);
if (!/^\d{4}-\d{2}-\d{2}$/.test(to)) errors.push('params.window_to must be YYYY-MM-DD, got: ' + to);
if (errors.length === 0 && new Date(from + 'T00:00:00Z') > new Date(to + 'T00:00:00Z')) errors.push('window_from is after window_to');
if (errors.length === 0 && new Date(to + 'T00:00:00Z') >= new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z')) {
  errors.push('window_to ' + to + ' is today or later - a period can only be audited once it is complete');
}
const runId = String(p.run_id || ('manual-' + from.slice(0, 7) + '-' + new Date().toISOString().slice(11, 19).replace(/:/g, '')));
// The SLOT, never the value. This line is what makes a rotation verifiable: once the caller
// is switched, a run logging secret_slot_matched 'rotating' proves live traffic is on the new
// secret, and only then is the old slot safe to delete.
console.log(JSON.stringify({ stage: 'realticket_validate_inputs', run_id: runId,
  via_http: viaHttp, secret_slot_matched: secretSlot,
  accepted_slots: ACCEPTED_WEBHOOK_SECRETS.map(function (c) { return c.slot; }),
  note: 'slot names only - the secret value is never logged, and it must never be added ' +
        'here even temporarily: every log line lands in the stored execution record.' }));

return [{ json: { ok: errors.length === 0, errors: errors, webhook_secret_slot: secretSlot, params: {
  run_id: runId,
  check_id: (smoke ? 'SMOKE-' : '') + 'applicant-real-ticket',
  check_name: 'Applicant Real Ticket',
  trigger: 'manual',
  smoke: smoke,
  started_at: new Date().toISOString(),
  run_date: new Date().toISOString(),
  window_from: from,
  window_to: to,
  window_defaulted: defaulted,
  max_applicants: Number(p.max_applicants || 0),
  only_applicants: Array.isArray(p.only_applicants) ? p.only_applicants.map(String) : [],
  constants: { expense_id: 137, expense_code: 'FT 07', ticket_type: 'REAL', page_size: 40, sibling_dummy_expense_id: 492 },
  delivery: { portal: false, data_tables: true, runs_log: true, email: false },
  callback_url: String(p.callback_url || ''),
  erp_auth: { bearer: bearer, token_bare: bearer.replace(/^Bearer\s+/, ''), device_id: deviceId, acting_user: tokenUser }
} } }];

const r = $input.first().json || {};
if (r.statusCode !== 200) {
  const msg = JSON.stringify(r.body || {});
  if (msg.indexOf('Token is expired') !== -1 || msg.indexOf('498') !== -1) {
    throw new Error('ERP TOKEN EXPIRED. The bearer supplied with this run is no longer valid (ERP answers HTTP 500 with "Token not valid, {Token is expired}", not a 401). Run stopped; nothing was scored. Supply a fresh token and re-run.');
  }
  if (msg.indexOf('INSUFFICIENT_PERMISSIONS') !== -1) throw new Error('ERP DENIED THE POPULATION SURFACE: INSUFFICIENT_PERMISSIONS on advancesearchNew / pagecode ManageTransactions. This is an access finding to report, not an error to route around. Run stopped; nothing was scored.');
  if (msg.indexOf('SecurityException') !== -1) throw new Error('ERP DENIED THE POPULATION SURFACE: SecurityException on advancesearchNew / pagecode ManageTransactions. Run stopped; nothing was scored.');
  throw new Error('POPULATION COUNT CALL FAILED with HTTP ' + r.statusCode + ': ' + msg.slice(0, 300) + '. Run stopped; nothing was scored.');
}
const body = r.body || {};
const total = Number(body.totalElements);
if (!isFinite(total)) throw new Error('POPULATION COUNT UNAVAILABLE: advancesearchNew returned no totalElements, so completeness cannot be proven. Run stopped; nothing was scored.');
if (!(total > 0)) throw new Error('EXPENSE 137 RETURNED ' + total + ' TRANSACTIONS for the window. An empty (or nonsensical) count is a broken query, never "no findings" - the run is aborted.');
const SIZE = 40;
const pages = Math.ceil(total / SIZE);
const out = [];
for (let p = 0; p < pages; p++) out.push({ json: { page: p, size: SIZE, total_expected: total, pages_expected: pages } });
return out;

const EXPENSE_ID = 137;
const SIZE = 40;
const pages = $input.all();
const plan = $('Build Page List').first().json;
const rows = [];
let reported = null;
const problems = [];
for (let i = 0; i < pages.length; i++) {
  const r = pages[i].json || {};
  if (r.statusCode !== 200) { problems.push('page ' + i + ' returned HTTP ' + r.statusCode); continue; }
  const b = r.body || {};
  const content = b.content;
  if (!Array.isArray(content)) { problems.push('page ' + i + ' carried no content array - the response shape changed'); continue; }
  if (reported === null && typeof b.totalElements === 'number') reported = b.totalElements;
  if (content.length > SIZE) problems.push('page ' + i + ' returned ' + content.length + ' rows, above the size ' + SIZE + ' asked for');
  for (const row of content) rows.push(row);
}
if (problems.length) throw new Error('POPULATION WALK FAILED: ' + problems.join('; ') + '. Never audit a truncated population. Run stopped; nothing was scored.');
if (rows.length === 0) throw new Error('EXPENSE 137 RETURNED ZERO ROWS across ' + pages.length + ' pages. An empty result is a broken query, never "no findings".');
const expected = Number(plan.total_expected);
if (reported === null) throw new Error('COMPLETENESS UNPROVABLE: no page reported totalElements. Run stopped; nothing was scored.');
if (rows.length !== reported) throw new Error('POPULATION INCOMPLETE: pulled ' + rows.length + ' rows but the envelope reports ' + reported + ' totalElements. "Not on a page" and "does not exist" are indistinguishable, and the false direction quietly clears a real finding. Run stopped; nothing was scored.');
if (isFinite(expected) && reported !== expected) {
  problems.push('the population moved mid-run: the pre-walk count said ' + expected + ', the walk reports ' + reported);
}
const foreign = [];
for (const r of rows) { const id = (r.expense || {}).id; if (id !== EXPENSE_ID && foreign.indexOf(id) === -1) foreign.push(id); }
if (foreign.length) throw new Error('FOREIGN EXPENSE IDS IN THE POPULATION: ' + JSON.stringify(foreign) + '. Only 137 belongs to this check (492 is the sibling Dummy Tickets check). The filter did not apply - never widen. Run stopped; nothing was scored.');
function redact(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/((?:Applicant|Maid)\s-\s)[^\/]*/g, '$1[NAME REDACTED]')
    .replace(/Passport\s*Number\s*-\s*\S+/gi, 'Passport Number - [REDACTED]');
}
const txns = [];
let maidRows = 0; let applicantPrefix = 0; let withId = 0; let neitherPrefix = 0;
let unknownTypeWithId = 0; let applicantNoId = 0; let disagreements = 0;
const typeCounts = {};
for (const r of rows) {
  const desc = String(r.description || '');
  const isMaid = /\/Maid\s-\s/.test(desc);
  const isApplicant = /\/Applicant\s-\s/.test(desc);
  const m = desc.match(/Applicant\sID\s-\s(\d+)/);
  const parsedId = m ? m[1] : null;
  const ttype = String(r.transactionType === undefined || r.transactionType === null ? '' : r.transactionType);
  typeCounts[ttype] = (typeCounts[ttype] || 0) + 1;
  if (isMaid) maidRows++;
  if (isApplicant) applicantPrefix++;
  if (!isMaid && !isApplicant) neitherPrefix++;
  if (parsedId) withId++;
  if (ttype === 'UNKNOWN' && parsedId) unknownTypeWithId++;
  if (isApplicant && !parsedId) applicantNoId++;
  const typeSaysApplicant = ttype === 'APPLICANT';
  const descSaysApplicant = isApplicant;
  if (typeSaysApplicant !== descSaysApplicant) disagreements++;
  if (isMaid) continue;
  const exm = desc.match(/^Ex(\d+)/);
  const amtSeg = desc.match(/\/(\d+\.\d{2})\/[A-Z]{3}\//);
  txns.push({
    txn_id: String(r.id),
    txn_date: String(r.date || ''),
    amount_signed: typeof r.amount === 'number' ? r.amount : null,
    ex_ref: exm ? exm[0] : null,
    desc_amount_text: amtSeg ? amtSeg[1] : null,
    transaction_type: ttype,
    applicant_id: parsedId,
    needs_detail: parsedId === null,
    type_disagrees: typeSaysApplicant !== descSaysApplicant,
    vat_amount: r.vatAmount === undefined ? null : r.vatAmount,
    license_code: (r.license || {}).code || null,
    note_redacted: redact(desc)
