}
return [{ json: {
  params: $('Validate Inputs').first().json.params,
  population: {
    txns_seen: rows.length,
    total_elements_reported: reported,
    pages_fetched: pages.length,
    population_complete: rows.length === reported,
    expense_id: EXPENSE_ID,
    applicant_scope_rows: txns.length,
    maid_rows_excluded: maidRows,
    applicant_prefix_rows: applicantPrefix,
    neither_prefix_rows: neitherPrefix,
    rows_with_applicant_id: withId,
    unknown_type_with_id: unknownTypeWithId,
    applicant_rows_without_id: applicantNoId,
    txn_type_disagreements: disagreements,
    transaction_types: typeCounts,
    warnings: problems
  },
  txns: txns
} }];

const src = $input.first().json;
const out = [];
for (const t of src.txns) { if (t.needs_detail) out.push({ json: { txn_id: t.txn_id, needed: true } }); }
// Never emit zero items - a downstream node that is skipped takes the whole
// chain with it, and the run would report success having scored nothing.
if (out.length === 0) return [{ json: { txn_id: null, needed: false } }];
return out;

const src = $('Population Guard').first().json;
const params = src.params;
const txns = src.txns.map(function (t) { return Object.assign({}, t); });

// Gate 3 (Order 20) - identity from the PLURAL applicants array. Fallback only,
// for the rows where the description carried no id. Never a name lookup.
let detailReads = 0;
let detailResolved = 0;
const needing = [];
for (const t of txns) { if (t.needs_detail) needing.push(t); }
let details = [];
