if (details.length && details.length !== needing.length) {
  throw new Error('DETAIL FALLBACK PAIRING BROKEN: ' + needing.length + ' rows needed a detail read but ' + details.length + ' responses came back. Refusing to pair by guess. Run stopped; nothing was scored.');
}
for (let i = 0; i < needing.length; i++) {
  const d = details[i] ? (details[i].json || {}) : null;
  detailReads++;
  if (d && d.statusCode === 200) {
    const b = d.body || {};
    const arr = Array.isArray(b.applicants) ? b.applicants : [];
    const id = (arr[0] && arr[0].applicant && arr[0].applicant.id !== undefined) ? String(arr[0].applicant.id) : null;
    if (id) { needing[i].applicant_id = id; needing[i].identity_source = 'detail_applicants_array'; detailResolved++; }
    else { needing[i].identity_source = 'unresolvable'; }
  } else { needing[i].identity_source = 'detail_read_failed'; }
}
for (const t of txns) { if (!t.identity_source) t.identity_source = t.applicant_id ? 'description_parse' : 'unresolvable'; }

// Gate 5 (Order 35) - net each Ex group BEFORE anything counts. Match by
// reference first; the retained refund fee means the pair does not sum to zero,
// so an exact equal-and-opposite test finds almost nothing.
const groups = {};
for (const t of txns) {
  const k = t.ex_ref || ('__noref_' + t.txn_id);
  if (!groups[k]) groups[k] = [];
  groups[k].push(t);
}
const nettedRefs = [];
const unmatchableNegatives = [];
for (const k of Object.keys(groups)) {
  const g = groups[k];
  let pos = 0; let neg = 0;
  for (const t of g) { const a = Number(t.amount_signed); if (!isFinite(a)) continue; if (a > 0) pos += a; else neg += a; }
