const SEV = { red: 1, verifier: 2, pending: 3, clean: 4 };
const REFUNDED_STATUS = ['REFUNDED', 'REFUND_SENT_TO_PAYERS'];
const NOT_DUE_STATUS = ['ISSUED', 'PENDING_REFUND', 'REQUESTED'];
const SHELL_STATUS = ['CANCELED', 'REQUESTED'];
function norm(v) { return String(v === undefined || v === null ? '' : v).trim(); }
