function gate7_moneyless(t) {
  return isEmptyAmt(t.amountInAED) && SHELL_STATUS.indexOf(norm(t.status)) !== -1;
}
function scoreTicket(t, ctx) {
  const outcome = t.ticketOutcome ? norm(t.ticketOutcome.label) : '';
  const status = norm(t.status);
  const amt = num(t.amountInAED);
  const cur = (t.currency && t.currency.name) ? norm(t.currency.name) : '';
