    return { gate: 15, verdict: 'verifier', reason: 'lost_outcome_with_refunded_status_conflict' };
  }
  if (outcome === 'Used') return { gate: 9, verdict: 'clean', reason: 'flown' };
  if (outcome === 'Refunded' || REFUNDED_STATUS.indexOf(status) !== -1 || ctx.allTimeReversal) {
