    return { gate: 10, verdict: 'clean', reason: viaAllTime ? 'all_time_reversal_found' : 'refunded' };
  }
  if (outcome === 'Lost' || status === 'REFUND_FAILED') {
    return { gate: 11, verdict: 'red', reason: outcome === 'Lost' ? 'lost' : 'refund_failed', unpriced: amt === null, loss: true };
  }
  if (amt === null || amt === 0) {
    return { gate: 12, verdict: 'pending', reason: amt === null ? 'amount_unknown' : 'amount_zero' };
  }
