    for (let j = 0; j < live.length; j++) {
      if (i === j) continue;
      const aTo = code(live[i].t.toLocationCode);
      const bFrom = code(live[j].t.fromLocationCode);
      if (aTo !== null && bFrom !== null && aTo === bFrom) {
        return { answer: 'one_journey_in_legs', legs: [live[i].id, live[j].id] };
      }
    }
  }
  for (const s of live) {
    const lay = Array.isArray(s.t.layover) ? s.t.layover : [];
    if (!lay.length) continue;
    for (const other of live) {
      if (other === s) continue;
      const oTo = code(other.t.toLocationCode);
      for (const L of lay) {
        const lc = code(L && (L.code || L.name));
        if (lc !== null && oTo !== null && String(lc).indexOf(String(oTo)) !== -1) {
          return { answer: 'covered_by_layover', legs: [s.id, other.id] };
        }
      }
    }
  }
  return null;
}
function findSameRouteUnrecovered(live) {
  for (let i = 0; i < live.length; i++) {
    for (let j = i + 1; j < live.length; j++) {
      const a = live[i], b = live[j];
      const aF = code(a.t.fromLocationCode), aT = code(a.t.toLocationCode);
      const bF = code(b.t.fromLocationCode), bT = code(b.t.toLocationCode);
      if (aF === null || aT === null || bF === null || bT === null) continue;
      if (aF === bF && aT === bT && a.result.gate !== 10 && b.result.gate !== 10) {
        return { answer: 'same_route_unrecovered', legs: [a.id, b.id] };
      }
    }
  }
  return null;
}
function duplicateQuestion(scored, count) {
  if (count < 2) return { gate: null, answer: 'not_triggered', gate14: null, gate15: null };
  const live = scored.filter(function (s) { return !s.moneyless; });
  // Both tests are evaluated. Gate 14 used to return on its first match, which
  // MASKED gate 15 on an applicant who had connecting legs AND a repeated route -
  // observed on run 93510. Gate 15 routes to review, which outranks gate 14's clean,
  // so it takes precedence and gate 14's answer is still recorded alongside it.
  const g14 = findConnecting(live);
  const g15 = findSameRouteUnrecovered(live);
  if (g15) return { gate: 15, answer: g15.answer, legs: g15.legs,
    gate14: g14 ? g14.answer : null, gate15: g15.answer };
  if (g14) return { gate: 14, answer: g14.answer, legs: g14.legs, gate14: g14.answer, gate15: null };
  return { gate: null, answer: 'count_triggered_nothing_matched', gate14: null, gate15: null };
}
function applyEscalations(verdict, reason, escalations) {
  let v = verdict, r = reason;
  for (const e of (escalations || [])) { if (SEV[e.verdict] < SEV[v]) { v = e.verdict; r = e.reason; } }
  return { verdict: v, reason: r };
}
function scoreApplicant(input) {
  const runDate = new Date(input.run_date);
  if (input.profile_reachable !== 200) {
    return { applicant_id: input.applicant_id, case_verdict: 'pending', case_reason: 'erp_unreadable_outage',
      infrastructure: true, exposure_aed: 0, unpriced_reds: 0, exposure_is_complete: true, tickets: [],
      duplicate_question: { gate: null, answer: 'not_evaluated' }, count_in_window: null, case_escalations: [] };
  }
  if (!input.applicant_id) {
    return { applicant_id: null, case_verdict: 'verifier', case_reason: 'applicant_id_unresolvable',
      exposure_aed: 0, unpriced_reds: 0, exposure_is_complete: true, tickets: [],
      duplicate_question: { gate: null, answer: 'not_evaluated' }, count_in_window: null, case_escalations: [] };
  }
  const all = Array.isArray(input.tickets) ? input.tickets : [];
  const real = all.filter(function (t) { return norm(t.ticketType) === 'REAL'; });
  const unknownType = all.filter(function (t) { return norm(t.ticketType) === ''; });
  const scored = real.map(function (t) {
    const moneyless = gate7_moneyless(t);
    const inWindow = input.in_window_ticket_ids ? input.in_window_ticket_ids.indexOf(t.id) !== -1 : null;
    return { id: t.id, t: t, moneyless: moneyless, in_window: inWindow,
      result: moneyless ? { gate: 7, verdict: 'excluded', reason: 'no_money_not_a_ticket' }
        : scoreTicket(t, { runDate: runDate, allTimeReversal: (input.all_time_reversal_ticket_ids || []).indexOf(t.id) !== -1 }) };
  });
  const count = scored.filter(function (s) { return !s.moneyless && s.in_window === true; }).length;
  const dq = duplicateQuestion(scored, count);
  const verdicts = scored.filter(function (s) { return s.result.verdict !== 'excluded'; });
  let caseVerdict = 'pending'; let caseReason = 'no_scored_ticket';
  if (verdicts.length) {
    let best = null;
    for (const s of verdicts) { if (best === null || SEV[s.result.verdict] < SEV[best.result.verdict]) best = s; }
    caseVerdict = best.result.verdict; caseReason = best.result.reason;
  }
  // Case-level escalations are recorded as DATA, not folded into the verdict here.
  // Every later stage recomputes the case verdict as the worst of its tickets, and
  // a stage that recomputed without re-applying these silently cleared a case the
  // earlier gate had routed - observed on run 93477.
  const escalations = [];
  // A count of 0 is only a contradiction when a charge SURVIVED netting and still no
  // ticket ties to it. Where every in-window charge was reversed, a count of 0 is the
  // expected outcome of gate 5, not a contradiction - flagging it put 15 correctly
  // handled applicants into the review queue on run 93510.
  if (count === 0 && input.reached_via_expense_137 && input.has_unnetted_positive_in_window_txn) {
    escalations.push({ verdict: 'verifier', reason: 'zero_count_contradiction' });
  }
  if (unknownType.length) escalations.push({ verdict: 'verifier', reason: 'ticket_type_absent' });
  if (input.txn_type_disagrees) escalations.push({ verdict: 'pending', reason: 'txn_type_disagreement' });
  const esc = applyEscalations(caseVerdict, caseReason, escalations);
  caseVerdict = esc.verdict; caseReason = esc.reason;
  // Gate 15 is deliberately NOT in that list: the verifier can answer it, so it is
  // re-applied conditionally in Adjudicate instead of unconditionally.
  if (dq.gate === 15 && SEV['verifier'] < SEV[caseVerdict]) { caseVerdict = 'verifier'; caseReason = 'same_route_unrecovered'; }
  const reds = scored.filter(function (s) { return s.result.loss === true; });
  const exposure = reds.reduce(function (a, s) { const v = num(s.t.amountInAED); return a + (v === null ? 0 : v); }, 0);
  const unpricedReds = reds.filter(function (s) { return num(s.t.amountInAED) === null; }).length;
  const exposureInWindow = reds.filter(function (s) { return s.in_window === true; })
    .reduce(function (a, s) { const v = num(s.t.amountInAED); return a + (v === null ? 0 : v); }, 0);
  return {
    applicant_id: input.applicant_id, case_verdict: caseVerdict, case_reason: caseReason,
    exposure_aed: Math.round(exposure * 100) / 100,
    explained_aed: 0,
    unrecovered_aed: Math.round(exposure * 100) / 100,
    exposure_in_window_aed: Math.round(exposureInWindow * 100) / 100,
    unpriced_reds: unpricedReds, exposure_is_complete: unpricedReds === 0,
    count_in_window: count, duplicate_question: dq,
    case_escalations: escalations,
    has_positive_in_window_txn: input.has_positive_in_window_txn === true,
    has_unnetted_positive_in_window_txn: input.has_unnetted_positive_in_window_txn === true,
    all_in_window_charges_reversed: input.has_positive_in_window_txn === true && input.has_unnetted_positive_in_window_txn !== true,
    ticket_type_absent: unknownType.length > 0,
    non_aed_present: scored.some(function (s) { return s.result.reason === 'non_aed_currency_unmeasured'; }),
    tickets_real: real.length,
    tickets_moneyless: scored.filter(function (s) { return s.moneyless; }).length,
    tickets: scored.map(function (s) {
      return { id: s.id, gate: s.result.gate, verdict: s.result.verdict, reason: s.result.reason,
        loss: s.result.loss === true, explained: false,
        amount_in_aed: num(s.t.amountInAED), in_window: s.in_window,
        route: norm(s.t.fromLocationCode) + '>' + norm(s.t.toLocationCode),
        status: norm(s.t.status), outcome: s.t.ticketOutcome ? norm(s.t.ticketOutcome.label) : '',
        refund_reason: s.t.refundReason ? norm(s.t.refundReason.label) : '',
        flight_date: norm(s.t.flightTicketDate),
        unrecognised: s.result.unrecognised || null };
    })
  };
}

// ---- n8n wrapper. Ties each ticket to the in-window transaction that paid for
// it (gate 8), then runs the gates above.
const src = $('Resolve Identity + Net Reversals').first().json;
const params = src.params;
const runDate = params.run_date;
const applicantIds = src.applicant_ids;
const responses = $input.all();
if (responses.length !== applicantIds.length) {
  throw new Error('TICKET READ PAIRING BROKEN: ' + applicantIds.length + ' applicants were queued but ' + responses.length + ' responses came back. Refusing to pair by guess. Run stopped; nothing was scored.');
}
let unreachable = 0;
const cases = [];
for (let i = 0; i < applicantIds.length; i++) {
  const id = applicantIds[i];
  const r = responses[i].json || {};
  const status = r.statusCode === undefined ? null : r.statusCode;
  const body = r.body || {};
  const txt = JSON.stringify(body);
  if (status !== 200 && (txt.indexOf('Token is expired') !== -1 || txt.indexOf('498') !== -1)) {
    throw new Error('ERP TOKEN EXPIRED mid-run while reading applicant tickets. Partial results are never emitted. Run stopped.');
  }
  const ft = body.flightsTickets;
  const arr = (ft && Array.isArray(ft.requestFlightTicketActions)) ? ft.requestFlightTicketActions : null;
  const reachable = (status === 200 && arr !== null) ? 200 : (status === null ? 0 : status);
  if (reachable !== 200) unreachable++;
  const txns = src.by_applicant[id] || [];
  const inWindowPositives = txns.filter(function (t) {
    return Number(t.amount_signed) > 0 && t.ex_group_reversed !== true;
  });
  const hasPositive = txns.some(function (t) { return Number(t.amount_signed) > 0; });
  const hasUnnettedPositive = inWindowPositives.length > 0;
  const typeDisagrees = txns.some(function (t) { return t.type_disagrees === true; });
  const tieIds = [];
  const untied = [];
  if (arr) {
    for (const t of arr) {
      if (norm(t.ticketType) !== 'REAL') continue;
      const a = num(t.amountInAED);
      if (a === null) continue;
      let tied = false;
      for (const tx of inWindowPositives) {
        const byText = tx.desc_amount_text !== null && Math.abs(Number(tx.desc_amount_text) - a) < 0.011;
        const bySigned = tx.amount_signed !== null && Math.abs(Number(tx.amount_signed) - a) < 0.011;
        if (byText || bySigned) { tied = true; break; }
      }
      if (tied) tieIds.push(t.id); else untied.push(t.id);
    }
  }
  const reversedTicketIds = [];
  if (arr) {
    const reversedTxns = txns.filter(function (t) { return t.ex_group_reversed === true; });
    for (const t of arr) {
      const a = num(t.amountInAED);
      if (a === null) continue;
      for (const tx of reversedTxns) {
        const byText = tx.desc_amount_text !== null && Math.abs(Number(tx.desc_amount_text) - a) < 0.011;
        if (byText) { reversedTicketIds.push(t.id); break; }
      }
    }
  }
  const scored = scoreApplicant({
    run_date: runDate,
    applicant_id: id,
    profile_reachable: reachable,
    tickets: arr || [],
    in_window_ticket_ids: tieIds,
    all_time_reversal_ticket_ids: reversedTicketIds,
    reached_via_expense_137: true,
    has_positive_in_window_txn: hasPositive,
    has_unnetted_positive_in_window_txn: hasUnnettedPositive,
    txn_type_disagrees: typeDisagrees
  });
  scored.txn_ids_in_window = txns.map(function (t) { return t.txn_id; });
  scored.ex_refs = txns.map(function (t) { return t.ex_ref; }).filter(Boolean);
  scored.netted_ex_refs = txns.filter(function (t) { return t.ex_group_reversed === true; }).map(function (t) { return t.ex_ref; }).filter(Boolean);
  scored.txn_type_disagrees = txns.some(function (t) { return t.type_disagrees === true; });
  scored.profile_reachable = reachable;
  scored.tickets_untied_to_window = untied.length;
  scored.notes_redacted = txns.map(function (t) { return t.note_redacted; });
  cases.push(scored);
}
return [{ json: {
  params: params,
  population: Object.assign({}, src.population, { ticket_reads: responses.length, applicants_unreachable: unreachable }),
  netted_ex_refs_all: src.netted_ex_refs,
  unattributable_txn_ids: src.unattributable_txn_ids,
  cases: cases
} }];

const src = $input.first().json;
// One all-time call per applicant still unresolved after the first pass - never
// one per transaction. Gate 10's second limb: the window truncates the refund.
const need = [];
for (const c of src.cases) {
  if (c.infrastructure) continue;
  if (c.case_verdict === 'red' || c.case_verdict === 'verifier' || c.duplicate_question.gate === 15) need.push(c.applicant_id);
}
return [{ json: { queued_applicant_ids: need, queued_count: need.length, params: src.params } }];

const q = $input.first().json.queued_applicant_ids || [];
const out = [];
for (const id of q) out.push({ json: { applicant_id: id } });
if (out.length === 0) return [{ json: { applicant_id: null, skip: true } }];
return out;

// ---- Gate 10 second limb. The all-time reversal search has now run for every
// applicant that was still unresolved, so re-score with it in hand.
const src = $('Score Deterministic').first().json;
const params = src.params;
const queued = $('Select All-Time Lookups').first().json.queued_applicant_ids || [];
let responses = [];
try { responses = $('Get All-Time Reversals').all(); } catch (e) { responses = []; }
const reversalsByApplicant = {};
let reads = 0; let incomplete = 0;
if (queued.length && responses.length && responses.length === queued.length) {
  for (let i = 0; i < queued.length; i++) {
    reads++;
    const r = responses[i].json || {};
    if (r.statusCode !== 200) { incomplete++; continue; }
    const b = r.body || {};
    const content = Array.isArray(b.content) ? b.content : null;
    if (content === null) { incomplete++; continue; }
    // An empty history counts as evidence ONLY when the walk is provably complete.
    if (typeof b.totalElements === 'number' && content.length < b.totalElements) { incomplete++; continue; }
    const amounts = [];
    for (const row of content) {
      const amt = typeof row.amount === 'number' ? row.amount : null;
      if (amt !== null && amt < 0) {
        const d = String(row.description || '');
        const m = d.match(/\/(\d+\.\d{2})\/[A-Z]{3}\//);
        if (m) amounts.push(Number(m[1]));
      }
    }
    reversalsByApplicant[queued[i]] = { amounts: amounts, complete: true };
  }
} else if (queued.length && responses.length !== queued.length) {
  incomplete = queued.length;
}
const cases = [];
let recleared = 0;
for (const c of src.cases) {
  const rev = reversalsByApplicant[c.applicant_id];
  c.all_time_refund_searched = queued.indexOf(c.applicant_id) !== -1;
  c.all_time_refund_complete = !!(rev && rev.complete);
  if (rev && rev.complete && rev.amounts.length) {
    let changed = false;
    for (const t of c.tickets) {
      if (t.verdict !== 'red') continue;
      const a = t.amount_in_aed;
      if (a === null) continue;
      for (const ra of rev.amounts) {
        if (Math.abs(ra - a) <= Math.max(1, a * 0.05)) {
          // The money came back, so this is no longer money out at all.
          t.gate = 10; t.verdict = 'clean'; t.reason = 'all_time_reversal_found'; t.loss = false; changed = true; break;
        }
      }
    }
    if (changed) {
      recleared++;
      const SEVL = { red: 1, verifier: 2, pending: 3, clean: 4 };
      let best = null;
      for (const t of c.tickets) { if (t.verdict === 'excluded') continue; if (best === null || SEVL[t.verdict] < SEVL[best.verdict]) best = t; }
      if (best) { c.case_verdict = best.verdict; c.case_reason = best.reason; }
      // Re-apply the case-level escalations. Recomputing the case verdict from its
      // tickets WITHOUT this silently cleared a routed case on run 93477.
      for (const e of (c.case_escalations || [])) {
        if (SEVL[e.verdict] < SEVL[c.case_verdict]) { c.case_verdict = e.verdict; c.case_reason = e.reason; }
      }
      if (c.duplicate_question && c.duplicate_question.gate === 15 && SEVL['verifier'] < SEVL[c.case_verdict]) {
        c.case_verdict = 'verifier'; c.case_reason = 'same_route_unrecovered';
      }
      const losses = c.tickets.filter(function (t) { return t.loss === true; });
      c.exposure_aed = Math.round(losses.reduce(function (a, t) { return a + (t.amount_in_aed === null ? 0 : t.amount_in_aed); }, 0) * 100) / 100;
      c.unrecovered_aed = c.exposure_aed;
      c.explained_aed = 0;
      c.exposure_in_window_aed = Math.round(losses.filter(function (t) { return t.in_window === true; }).reduce(function (a, t) { return a + (t.amount_in_aed === null ? 0 : t.amount_in_aed); }, 0) * 100) / 100;
      c.unpriced_reds = losses.filter(function (t) { return t.amount_in_aed === null; }).length;
      c.exposure_is_complete = c.unpriced_reds === 0;
    }
  }
  cases.push(c);
}
return [{ json: Object.assign({}, src, {
  cases: cases,
  population: Object.assign({}, src.population, { alltime_reads: reads, alltime_incomplete: incomplete, alltime_recleared: recleared })
}) }];

const src = $input.first().json;
const params = src.params;
const tasks = [];
for (const c of src.cases) {
  if (c.infrastructure) continue;
  const notes = (c.notes_redacted || []).join('\n---\n');
  // Verifier rule 1 (Order 125) - one task per Lost / REFUND_FAILED ticket.
  for (const t of c.tickets) {
    if (t.verdict !== 'red') continue;
    tasks.push({ rule: 'V1', applicant_id: c.applicant_id, ticket_id: String(t.id), amount_aed: t.amount_in_aed,
      prompt: 'RULE: V1 - does the written record explain why a real ticket was neither flown nor refunded?\n\n'
        + 'APPLICANT: ' + c.applicant_id + '\nTICKET: ' + t.id + '\nROUTE: ' + t.route
        + '\nAMOUNT AED: ' + (t.amount_in_aed === null ? 'UNKNOWN - price it only if the record states it' : t.amount_in_aed)
        + '\nTICKET STATUS: ' + t.status + '\nTICKET OUTCOME: ' + t.outcome
        + '\nERP REFUND REASON: ' + (t.refund_reason || '(empty)')
        + '\nALL-TIME REVERSAL SEARCH RAN: ' + (c.all_time_refund_searched ? 'yes' : 'no')
        + '\nALL-TIME SEARCH PROVABLY COMPLETE: ' + (c.all_time_refund_complete ? 'yes' : 'no')
        + '\n\nTICKETING NOTES (names and passport numbers removed at source):\n' + notes });
  }
  // Verifier rule 2 (Order 128) - the same-route pair.
  if (c.duplicate_question && c.duplicate_question.gate === 15) {
    const legs = c.duplicate_question.legs || [];
    const pair = c.tickets.filter(function (t) { return legs.indexOf(t.id) !== -1; });
    tasks.push({ rule: 'V2', applicant_id: c.applicant_id, ticket_id: legs.join('+'), amount_aed: null,
      prompt: 'RULE: V2 - was a second real ticket on the same route a justified rebooking?\n\n'
        + 'APPLICANT: ' + c.applicant_id + '\nTICKET COUNT IN WINDOW: ' + c.count_in_window
        + '\nTHE PAIR:\n' + pair.map(function (t) {
            return '  ticket ' + t.id + ' route ' + t.route + ' AED ' + t.amount_in_aed + ' status ' + t.status
              + ' outcome ' + (t.outcome || '(empty)') + ' refundReason ' + (t.refund_reason || '(empty)');
          }).join('\n')
        + '\nALL-TIME REVERSAL SEARCH RAN: ' + (c.all_time_refund_searched ? 'yes' : 'no')
        + '\nALL-TIME SEARCH PROVABLY COMPLETE: ' + (c.all_time_refund_complete ? 'yes' : 'no')
        + '\n\nTICKETING NOTES (names and passport numbers removed at source):\n' + notes });
  }
}
return [{ json: { task_count: tasks.length, tasks: tasks, params: params } }];

const t = $input.first().json.tasks || [];
const out = [];
for (const x of t) out.push({ json: x });
return out;

parameters.inputSchema:
{
  "type": "object",
  "required": ["verdict", "confidence", "reasoning", "quote", "quote_source", "explanation_states_why", "route_to", "evidence_complete"],
  "properties": {
    "verdict": {
      "type": "string",
      "enum": ["clean - explained", "clean - rebooking justified", "finding - unexplained", "pending - evidence claimed, not verified"],
      "description": "One of the four, exactly as written. Never paraphrased."
    },
    "confidence": {
      "type": "string",
      "enum": ["high", "medium", "low"],
      "description": "A low-confidence clearance is not a clearance - return 'finding - unexplained' instead."
    },
    "reasoning": {
      "type": "string",
      "description": "Two or three sentences. Say which piece of evidence settled it and why the others did not."
    },
    "quote": {
      "type": "string",
      "description": "The VERBATIM sentence the verdict rests on, copied character for character from the evidence given. Empty string only when the verdict is not a clearance and no sentence is being relied on. Never include a person's name."
    },
    "quote_source": {
      "type": "string",
      "description": "Which evidence line the quote came from, e.g. 'refundReason' or 'ticketing note'."
    },
    "explanation_states_why": {
      "type": "boolean",
      "description": "True only if the quoted text states a DECISION or GROUND that accounts for the money, not merely what happened or who did it."
    },
    "route_to": {
      "type": "string",
      "enum": ["none", "accounting", "recruitment", "auditor"],
      "description": "Who has to act next. 'none' when the ticket is cleared."
    },
    "evidence_complete": {
      "type": "boolean",
      "description": "False when the all-time refund search did not run or was not provably complete, so absence of a refund could not be established."
    },
    "amount_aed": {
      "type": "number",
      "description": "Echo of the amount as given in the facts. Never recomputed."
    }
  }
}

parameters.jsCode:
const tasks = $('Select Verifier Cases').first().json.tasks || [];
const outs = $input.all();
const verdicts = [];
let down = 0;
for (let i = 0; i < tasks.length; i++) {
  const o = outs[i] ? (outs[i].json || {}) : null;
  const parsed = o ? (o.output || o) : null;
  if (!parsed || !parsed.verdict) {
    down++;
    verdicts.push(Object.assign({}, tasks[i], { verdict: 'unresolved', decided_by: 'none', verifier_down: true,
      why_no_model: 'the verifier returned no parsable verdict', confidence: 'low', reasoning: '', quote: '',
      quote_source: '', explanation_states_why: false, route_to: 'auditor', evidence_complete: false }));
    continue;
  }
  verdicts.push(Object.assign({}, tasks[i], {
    verdict: String(parsed.verdict), decided_by: 'model', verifier_down: false, why_no_model: '',
    confidence: String(parsed.confidence || 'low'), reasoning: String(parsed.reasoning || ''),
    quote: String(parsed.quote || ''), quote_source: String(parsed.quote_source || ''),
    explanation_states_why: parsed.explanation_states_why === true,
    route_to: String(parsed.route_to || 'auditor'),
    evidence_complete: parsed.evidence_complete !== false
  }));
}
return [{ json: { verdicts: verdicts, verifier_down: down } }];

// Gate 6 (Order 40) RE-AGGREGATION, after the verifier answers.
// Every verifier rule's clean is scoped to ONE TICKET. One explained loss must
// never close a sibling unexplained one, so the case verdict is recomputed here
// as the worst of the applicant's remaining tickets.
const src = $('Rescore With Reversals').first().json;
const params = src.params;
const bag = { verdicts: [], verifier_down: 0 };
for (const it of $input.all()) {
  const j = it.json || {};
