    'Counts this batch: ' + v.counts.ok + ' ok, ' + v.counts.server_error + ' server error, ' +
    v.counts.throttled + ' throttled, ' + v.counts.timeout + ' timed out, ' + v.counts.auth +
    ' auth (auth is NOT counted as degradation - see tools/erp_breaker.js). | ' +
    (v.samples.length ? 'First failures: ' + v.samples.join(' || ') + ' | ' : '') +
    'ERP is production and it is answering us badly. DO NOT re-fire this run to see if it ' +
    'passes, and DO NOT raise the thresholds - both add load to a system that is already ' +
    'failing, which is how ERP was taken down three times. Check ERP is healthy, then re-run ' +
    'from a capped cohort. ERP-LOAD-POLICY.md §5.';
}
// --- the guard: reads the run's baseline, decides, logs, and throws if tripped ---------------
//
// THE BASELINE HAS TO SURVIVE BETWEEN CHUNKS, and it cannot travel in the payload: WF-A builds
// every chunk item up front and hands them to Execute Workflow in `each` mode, so there is no
// point at which WF-A can put chunk N's measurement into chunk N+1's input. n8n's per-workflow
// static data is the only carrier left. It is saved at the end of an execution and is NOT
// written for manual test runs, so the baseline can legitimately be absent - which is why an
// absent baseline disables the latency check rather than defaulting it, and why every batch
// logs `baseline_carried`. A latency check that silently never fires is the false-clearance
// shape this project keeps finding; this one announces itself in the log chain instead.
function erpBreakerStatic() {
  try { return $getWorkflowStaticData('global') || {}; } catch (e) { return null; }
}
function erpBreakerGuard(opts) {
  const src = $('ERP Budget Gate').first().json || {};
  const runId = String(src.run_id || '');
  const t0 = Number(src.erp_t0);
  const elapsed = Number.isFinite(t0) && t0 > 0 ? Date.now() - t0 : null;

  const sd = erpBreakerStatic();
  // A new run must not inherit the previous run's baseline: ERP at 9am and ERP at 9pm are not
  // the same server, and comparing across runs would trip on the time of day.
  if (sd && sd.erp_breaker_run !== runId) { sd.erp_breaker_run = runId; sd.erp_breaker_baseline = {}; }
  const base = (sd && sd.erp_breaker_baseline) || {};

  // opts.config is the per-call-site override. It exists for ONE declared case - a phase whose
  // whole-batch 401 is a known account-scoped gap the flow already reports - and a call site
  // that passes it must say in writing why, next to the code. It is not a threshold dial.
  const v = erpBreakerEvaluate({
    phase: opts.phase, responses: opts.responses,
    elapsedMs: elapsed, callsMade: opts.callsMade,
    baselineMsPerCall: base[opts.key],
    pagecode: opts.pagecode, config: opts.config
  });

  console.log(JSON.stringify({ stage: 'erp_breaker', phase: opts.phase, key: opts.key,
    run_id: runId || null, chunk_index: src.chunk_index === undefined ? null : src.chunk_index,
    total: v.total, counts: v.counts, degraded_rate: v.degraded_rate,
    consecutive_max: v.consecutive_max, ms_per_call: v.ms_per_call,
    baseline_ms_per_call: v.baseline_ms_per_call, baseline_carried: v.baseline_carried,
    latency_multiple: v.latency_multiple, tripped: v.trip ? v.trip.code : null,
    // Logged on EVERY batch, tripped or not. A wall that a call site opted out of has to stay
    // visible in the run log, or the opt-out becomes the thing nobody can see.
    auth_wall: v.auth_wall, auth_wall_enforced: v.auth_wall_enforced,
    first_auth_index: v.first_auth_index,
    developer_message: v.developer_message, pagecode: v.pagecode,
    static_data_available: sd !== null,
    note: 'ERP-LOAD-POLICY.md §5. A 401 among successes is NOT degradation and is not counted ' +
          'as one - the permanent 401 on every replacement call would otherwise trip this on ' +
          'call five of every run ever fired. A batch where NOTHING succeeded is a different ' +
          'thing: it is a wall, it cannot heal, and it stops the run.' }));

  if (v.trip) throw new Error(erpBreakerMessage(v, opts.phase, runId));

  // The baseline is set from the first batch BIG enough to mean anything. A canary chunk of 50
  // amortises fixed overhead over 50 calls and reads slower per call than a chunk of 750, so
  // taking the baseline from it would inflate the threshold and make the breaker LESS sensitive
  // for the rest of the run - a safety check quietly weakened by the safety measure in front
  // of it.
  if (sd && !base[opts.key] && v.ms_per_call && opts.callsMade >= (opts.minCallsForBaseline || 200)) {
    base[opts.key] = v.ms_per_call;
    sd.erp_breaker_baseline = base;
    console.log(JSON.stringify({ stage: 'erp_breaker_baseline_set', key: opts.key,
      ms_per_call: v.ms_per_call, calls: opts.callsMade, run_id: runId || null }));
  }
}
// --- call site: the all-time-reversals fan-out ------------------------------------------------
// This node exists ONLY to judge the batch and hand it on unchanged, so that the generated 10 KB
// breaker block does not have to be pasted into Rescore With Reversals and make the interesting
// code the minority of that file.
//
// WHAT CAN AND CANNOT FIRE HERE, stated rather than implied:
//   consecutive_failures  - LIVE. Five 5xx/429/timeouts in a row abort the run.
//   degraded_rate         - CONDITIONAL. It needs 20 samples and this batch is one call per
//                           RED ticket selected for an all-time lookup, not per transaction - a
//                           clean month can be well under 20, and then only the consecutive rule
//                           is watching.
//   latency               - CANNOT FIRE, and that is not a defect. The rule compares this batch
//                           against a baseline from an EARLIER batch of the same key in the same
//                           run, and this fan-out happens exactly ONCE per run - there is no
//                           second batch to compare to. No erp_t0 is stamped and
//                           `baseline_carried` logs false. Said out loud because a latency check
//                           that silently never fires is the false-clearance shape this project
//                           keeps finding.
//
// The ERP nodes here all run with `neverError: true`, so an HTTP error arrives as an ITEM with a
// statusCode rather than as a thrown failure. That is what makes this breaker able to see them:
// it classifies the item. It is also why these nodes must stay on continueRegularOutput - an
// error OUTPUT would route the failures past this node and leave it counting only successes.
const _responses = $input.all().map(function (i) { return i.json; });
erpBreakerGuard({
  phase: 'All-time reversals (Applicant Real Ticket)',
  key: 'reversals',
  responses: _responses,
  callsMade: _responses.length,
  minCallsForBaseline: 20
});
// =================== END ERP CIRCUIT BREAKER ===================

// Pass the batch on untouched. Rescore With Reversals reads $('Get All-Time Reversals') by name.
// Returning the input items directly is n8n's passthrough and preserves paired-item lineage,
// which rebuilding them as {json: ...} would drop.
return $input.all();

// Capture Failure - the FIRST node on the error rail, and the reason the rail can still say what
// went wrong. CANONICAL COPY: tools/erp_capture_failure.js. Deployed by
// tools/make_capture_failure_ops.py; do not hand-edit a deployed copy without changing this one.
//
// WHY IT EXISTS. The rail used to run `failing node -> Release Lease (error) -> Fail Loudly`, and
// Release Lease (error) is an Execute Sub-workflow node with waitForSubWorkflow: true. That node
// does not pass its input through - it REPLACES the item with whatever the lease workflow
// returned. So by the time Fail Loudly read $input, the error payload was gone and every message
// it could produce was 'FAILED at "unknown node": unknown error'. Twelve of thirteen flows shipped
// that way (2026-08-23). The error is captured HERE, before the lease call can overwrite it.
//
// IT DOES NOT THROW. The release has to happen first, and a throw here would strand the lease -
// the exact hole the rail exists to close.
//
// ------------------------------------------------------------------------------------------
// v2, 2026-08-23, written after the FIRST time this rail ever fired for real (execution 99851).
// v1 read `error.message` and got 'unknown error' anyway, because AN n8n HTTP ERROR ITEM HAS NO
// error.message. What it has is:
//
//   { error: { statusCode: 500,
//              error: "<html>... type=Http Status 498 ... Access Token is missing or malformed
//                      &lt;LOGOUT&gt; ...</html>",     <- a STRING, sometimes HTML, sometimes JSON
//              isAxiosError: true,
//              response: { status: 500, headers: {...} } } }
//
// and the rest of the item is whatever flowed IN to the failing node - in 99851 that was the
// lease's own acquire payload, which is why `item.message` was undefined too.
//
// This was already written down. MV Overstay Fines' `Build Error Callback` says it almost word for
// word, from execution 76767 back in the same repo. It was not carried into the shared node, so
// every flow got the naive version. The lesson is in ERP-LOAD-POLICY.md.
// ------------------------------------------------------------------------------------------
// v3 + IDENTITY STAMP, 2026-08-24. Added after execution 100774 (MV Overstay Fines) stranded the
// ERP lease on a live run and three later audits queued behind a holder that had already exited.
//
// `Acquire ERP Lease` and `Release Lease (error)` there carried the IDENTICAL mapping - the
// expression  $('Validate Inputs').first().json.params.run_id  (braces omitted so this comment is
// not itself read as an expression). It resolved at the acquire and resolved to NOTHING at the
// error-rail release, in the SAME execution, with Validate Inputs demonstrably successful. n8n
// then DROPPED the field rather than sending null - the payload that reached the lease held mode,
// check_id and ignore_lease, all LITERALS, and no run_id at all. The lease refused, correctly: it
// will not free a lease without knowing who holds it.
//
// The one thing that differs between the two nodes is the CURRENT ITEM. At the release the item
// is the synthetic one THIS node builds, and the cross-node lookup does not resolve from it.
// n8n's internal reason is NOT proven here and is deliberately not relied on: the fix does not
// need it. The identity is resolved HERE, where the lookup still works, and STAMPED ON THE ITEM,
// so the release reads it off $json and performs no lookup at all. The guarded lookup left on the
// release node is a second line of defence, not the mechanism.
//
// EVERY SOURCE IS TRIED IN ITS OWN try/catch AND THIS NODE STILL NEVER THROWS. A throw here would
// strand the lease AND lose the diagnostic - it is the node that makes a failure legible, so it
// is the last node in the flow that may fail.
// ------------------------------------------------------------------------------------------
const item = $input.first().json || {};
const raw = item.error;
const err = (raw && typeof raw === 'object') ? raw : {};

function firstString() {
  for (let i = 0; i < arguments.length; i++) {
    const v = arguments[i];
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return '';
}

// The status lives in three different places depending on how the node failed.
const status = Number(err.statusCode) || Number(err.response && err.response.status) ||
               Number(item.statusCode) || null;

// The text is a string that may be HTML, may be JSON, may be a plain throw message.
let text = firstString(err.message, typeof raw === 'string' ? raw : '', err.error,
                       item.message, err.description);
if (text && text.charAt(0) === '{') {
  try {
    const p = JSON.parse(text);
    text = firstString(p.message, p.error, p.detail, text);
  } catch (e) { /* not JSON after all - keep the raw string */ }
}
// ERP serves its refusals as a Whitelabel error PAGE. The sentence worth reading is the last
// <div>; everything around it is boilerplate that would bury the message in the run log.
if (/<html/i.test(text)) {
  const divs = text.match(/<div[^>]*>([^<]+)<\/div>/gi) || [];
  const inner = divs.map(function (d) { return d.replace(/<[^>]+>/g, '').trim(); })
                    .filter(function (t) { return t && !/^\w{3} \w{3} +\d/.test(t); });
  const joined = inner.join(' | ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  text = joined || text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 300);
}

// NAME THE DENIAL SHAPE, because it decides what the operator does next and the status code alone
// sends them the wrong way. A dropped ERP session appears as BOTH 401 and 5xx-498, and reading the
// status class first tells someone to go request a permission they already hold.
//
// <LOGOUT> IS AMBIGUOUS AND v2 GOT THIS WRONG. v2 read the marker and said flatly "the session is
// dead, go get a fresh token". Measured 2026-08-24: GET /accounting/transactions/{id} answers
// 401 "UNAUTHORIZED <LOGOUT>" while the SAME token, in the same second, gets HTTP 200 from
// /clientmgmt/contract/search/page. The session was fine; that API is simply not registered under
// the pagecode the node sends, and ERP dresses a permission refusal in the same marker as a dead
// session. Telling the operator to re-token there sends them round a loop that can never succeed.
//
// The discriminator is the developerMessage RESPONSE HEADER, which n8n does not put on the error
// item - so this node names both readings and says which header settles it, rather than guessing.
let shape = '';
if (/<LOGOUT>|UNAUTHENTICATED|Access Token is missing or malformed/i.test(text)) {
  shape = 'AMBIGUOUS <LOGOUT> - ERP uses this marker for TWO different things and the status code ' +
          'does not separate them. (a) The session really is dead: measured 2026-08-23, a session ' +
          'died 4h03m after its token was issued while the exp claim still had 2.5h to run, so the ' +
          'exp tells you nothing. (b) The API is not registered under the pagecode this node sends: ' +
          'measured 2026-08-24, GET /accounting/transactions/{id} returns this while the same token ' +
          'gets HTTP 200 elsewhere in the same second. SETTLE IT with the developerMessage response ' +
          'header: API_NOT_FOUND_FOR_PAGE or PAGE_CODE_MISSING means the REQUEST is wrong and ' +
          're-tokening will loop for ever; absent means the session or the permission is. Check ' +
          'another endpoint with the same token before you conclude anything.';
} else if (status === 503 || status === 502 || status === 504) {
  shape = 'ERP MODULE UNAVAILABLE - do not retry in a loop and do not re-token; this is not auth.';
} else if (status === 401 || status === 403) {
  shape = 'ACCESS DENIED with no dropped-session marker - read the developermessage header: a ' +
          'real permission gap is a FINDING to report, not something to route around.';
}

// The node name is only ever present when the failure came from a Code node or a sub-workflow
// throw. n8n does NOT put it on an HTTP error item, so this says so rather than inventing one.
const node = String((err.node && err.node.name) || item.node ||
                    (status ? 'an HTTP node (n8n does not name it on an HTTP error item)'
                            : 'unknown node'));

const message = [status ? 'HTTP ' + status : '', text || 'unknown error', shape]
  .filter(function (x) { return x; }).join(' - ');

// ----- IDENTITY STAMP (see the header) ---------------------------------------------------
// run_id is what `Release Lease (error)` sends the lease; check_id names the audit. Sources are
// tried in order of trustworthiness and each one is isolated, so a source that cannot resolve
// costs the next one nothing.
let runId = '';
let checkId = "applicant-real-ticket";
let runIdSource = '';
// MEASURED 2026-08-24 on the MV Overstay Fines rail - accessor diagnostic (execution 100943) and
// the pinned zero-ERP proof run (execution 100973, lease freed with reason "released by its
// holder"). On the error rail, from inside a Code node:
//
//   $('<a node with an error output>').isExecuted   -> true       it DID run
//   $('<a node with an error output>').all().length -> 0          and resolves to ZERO items
//   $('<a node with an error output>').first()      -> undefined  so .json THROWS
//   $('<the entry node, single output>').first()    -> RESOLVES
//
// THE DISCRIMINATOR IS THE ERROR OUTPUT, NOT DISTANCE FROM THIS NODE. A node wired with a SECOND
// output onto this rail resolves to THAT branch from here, and that branch is empty. A node with
// a SINGLE output resolves normally. So the ENTRY / CONTEXT node is tried FIRST and the
// validate-equivalent is demoted to a fallback. Round 2 of this fix put the validate node first
// and was PROVEN not to work by execution 100899, where run_id was stamped ''.
try {
  const s1 = ($('Run (webhook)').first().json || {}).body || {};
  if (!runId && s1.run_id) { runId = String(s1.run_id); runIdSource = "$('Run (webhook)').body.run_id"; }
} catch (e) { }
try {
  const s0 = ($('Validate Inputs').first().json || {}).params || {};
  if (!runId && s0.run_id) { runId = String(s0.run_id); runIdSource = "$('Validate Inputs').params.run_id"; }
  if (s0.check_id) checkId = String(s0.check_id);
} catch (e) { }

// The failing item itself, last: it belongs to this execution so it cannot name another run, but
// it is the least specific of the sources.
try {
  if (!runId && item && item.run_id) { runId = String(item.run_id); runIdSource = 'the failing item'; }
} catch (e) { }

console.log(JSON.stringify({ stage: 'capture_failure', run_id: runId || '(unresolved)',
  check_id: checkId, run_id_source: runIdSource || 'NONE',
  failed_node: node, status: status, error: message,
  lease_note: runId
    ? 'the error-rail release will name this run, so the ERP lease is freed'
    : 'NO run_id could be resolved. The release will be REFUSED by the lease, which is the ' +
      'correct refusal - it will not free a lease without knowing who holds it. The lease is ' +
      'still HELD: clear it with params.ignore_erp_lease on the next run, or wait out the ' +
      '3-hour staleness backstop.',
  note: 'Captured before Release Lease (error), which replaces the item with the lease\'s own ' +
        'output. The rest of the rail reads this node by name, and the release reads run_id / ' +
        'check_id off THIS item instead of looking the validate node up again.' }));

return [{ json: { run_id: runId, check_id: checkId,
                  _failure: { node: node, message: message, status: status,
                              at: new Date().toISOString() } } }];

// Run Config - the entry point for the monthly schedule and for a manual re-run.
//
// ADDED 2026-08-30. This flow used to have exactly one door, the webhook, and the ruling that
// audit flows run on a schedule with no inbound endpoint left it with none. This node shapes the
// SAME envelope the webhook delivered, so `Validate Inputs` and the 32 nodes that reference it
// are completely unchanged.
//
// NO `headers` KEY, ON PURPOSE. `Validate Inputs` guards its shared-secret comparison with
// `if (viaHttp)`, where viaHttp tests whether `raw.headers` is an object. Omitting the key means
// a scheduled run skips the secret check by that node's OWN design - nothing is bypassed, and the
// check still applies to anything arriving over HTTP.
//
// THE WINDOW IS NOT SET HERE. `Validate Inputs` already carries a `lastMonth()` default and uses
// it whenever params.window_from / window_to are absent, and it refuses any window whose end is
// today or later ('a period can only be audited once it is complete'). Re-deriving the month here
// would duplicate that rule in a second place and let the two drift. To pin a window for a
// deliberate one-off, add window_from / window_to to params below.
//
// ============================ ERP AUTH IS A CREDENTIAL NOW ============================
// RESOLVED 2026-08-30. The block that used to sit here read ERP_BEARER and ERP_DEVICE_ID from
// workflow variables and THREW when either was missing, and its own comment said the quiet part:
// "TOKENS LAST 24 HOURS, so this path cannot carry a monthly schedule on its own. The production
// answer is a stored ERP credential holding a production token, created at deployment."
//
// That is now done. The five ERP nodes authenticate through a stored httpBearerAuth credential,
// so the token no longer travels through this envelope and the gate no longer has anything to
// guard. Production is a read-only mirror - nobody can set a workflow variable there each month -
// so the credential was the only shape that could survive deployment.
//
// The concern behind the old throw still stands and is not lost: a run with no working token 401s
// on every call and would report the whole population as clean. That is now caught where it
// actually happens - the population gate refuses a cohort it could not read, and the circuit
// breaker stops a batch that ERP refuses outright.
// ======================================================================================
const ERP_DEVICE_ID = ($vars && $vars.ERP_DEVICE_ID) ? String($vars.ERP_DEVICE_ID) : '';

// A token left in ERP_BEARER is reported rather than used. It authorises nothing now, and a live
// token sitting in workflow settings persists in every version snapshot - so it should be cleared.
if ($vars && $vars.ERP_BEARER) {
  console.log(JSON.stringify({ stage: 'erp_bearer_ignored',
    note: 'A value is set in the ERP_BEARER workflow variable. It is NOT used - the ERP nodes ' +
          'authenticate through their stored credential. Please clear it.' }));
}

return [{ json: {
  body: {
    // bearer is deliberately empty: the credential carries it. device_id stays because the ERP
    // nodes still send it as a cookie; it renders empty when the variable is unset, and live
    // probes reach these endpoints on the Authorization header alone.
    erp_auth: { bearer: '', device_id: ERP_DEVICE_ID },
    params: {
      // window_from / window_to deliberately omitted - Validate Inputs defaults them to the
      // previous full calendar month. Set them here only to pin a one-off re-run.
      callback_url: ''   // no callbacks: the ruling removed portal delivery entirely
    }
  }
} }];
